<script>(function(){const totals={!!$paymentTotalsJson!!},tabs=document.querySelectorAll('[data-pay-tab]'),panes=document.querySelectorAll('[data-pay-pane]'),totalLabel=document.getElementById('secure-pay-total'),errorBox=document.getElementById('secure-pay-error');function money(v){return Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}function showError(m){if(!errorBox)return;errorBox.textContent=m||'Não foi possível processar o pagamento.';errorBox.classList.add('visible');errorBox.scrollIntoView({behavior:'smooth',block:'center'})}tabs.forEach(tab=>tab.addEventListener('click',()=>{const type=tab.dataset.payTab;tabs.forEach(x=>x.classList.toggle('active',x===tab));panes.forEach(x=>x.classList.toggle('active',x.dataset.payPane===type));if(totalLabel)totalLabel.textContent=money(totals[type])}));document.querySelectorAll('.secure-server-form').forEach(form=>form.addEventListener('submit',()=>{const btn=form.querySelector('button[type=submit]');if(btn){btn.disabled=true;btn.textContent=btn.dataset.loadingText||'Processando...'}}));@if($formas->contains('cartao')&&!empty($default['config']->mercadopago_public_key))try{const mp=new MercadoPago({!!$mercadoPagoPublicKeyJson!!},{locale:'pt-BR'}),bricksBuilder=mp.bricks();bricksBuilder.create('cardPayment','cardPaymentBrick_container',{initialization:{amount:Number(totals.cartao),payer:{email:{!!$clienteEmailJson!!}}},callbacks:{onReady:()=>{},onSubmit:(cardFormData)=>fetch({!!$cartaoUrlJson!!},{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':{!!$csrfTokenJson!!}},body:JSON.stringify(cardFormData)}).then(async r=>{const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Pagamento recusado.');window.location.href=d.redirect}).catch(e=>{showError(e.message);throw e}),onError:(e)=>{console.error(e);showError('Não foi possível carregar ou processar o cartão.')}}})}catch(e){console.error(e);showError('Falha ao inicializar o pagamento com cartão.')}@endif})();</script>